// Inicialização da Ordem de Compra Blindada
const body = $input.item.json.body || {};
const opportunityId = body.opportunityId || null;
const targetUrl = body.targetUrl || 'https://exemplo.com';
const price = Number(body.price || 0);
const orderId = 'ORD_' + Date.now();

const pixCode = `00020126580014BR.GOV.BCB.PIX0136${orderId}520400005303986540510.005802BR5915RADAR_HUB6009SAO_PAULO62070503***6304ABCD`;

return [{
  json: {
    orderId,
    opportunityId,
    targetUrl,
    finalPrice: price,
    pixCode,
    pixQrUrl: `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${orderId}`,
    status: 'PIX_PENDING'
  }
}];

